"""Durable state for high-level ZCode subagent delegations.

This module is the single writer of ``superagent.json`` in the local bridge
state directory.  It deliberately has no transport or tool wiring: the service
layer creates jobs here and then performs the real session RPCs.

Design boundaries
-----------------
* A job is bound to the source thread from the current MCP request.  Reads and
  mutations require that exact thread, so one chat cannot inspect or change
  another chat's delegation.
* Idempotency keys are generated by the bridge when absent and persisted.  The
  same key from the same source thread always returns the same job; it never
  creates a second delegation.
* Profiles are resolved as: explicit arguments, then bound profile, then the
  configured defaults.  Models and reasoning levels are validated against the
  real catalogue supplied by ``zcode_models``.  There is no silent model
  substitution.
* Queue contents stay in the local state directory only.  ``job_summary``
  never returns message text, task text, credentials or host launch data.
"""
from __future__ import annotations

import copy
import hashlib
import json
import os
import threading
import time
import uuid
from pathlib import Path

from .storage import read_json, state_dir, write_json

SCHEMA_VERSION = 1
CONTRACT_VERSION = 'superagent-contract-v1'
MAX_JOBS = 200
MAX_QUEUE_ITEMS = 20
MAX_MESSAGE_CHARS = 200000
MAX_IDEMPOTENCY_CHARS = 200
MAX_REPORT_BYTES = 16384
MAX_REPORT_STRING = 2000
MAX_REPORT_ITEMS = 50
MAX_REPORT_DEPTH = 4
PERMISSION_MODES = ('full_access', 'review_important_actions', 'ask_before_writes',
                    'always_ask', 'read_only')
PERMISSION_SOURCES = ('explicit_caller',)
WORKFLOW_MODES = ('disabled', 'onDemand', 'alwaysOn', 'native_default')
TRANSPORTS = ('desktop_native',)
STATUSES = ('created', 'dispatching', 'running', 'action_required', 'reported',
            'verified', 'send_uncertain', 'stalled', 'unobservable',
            'failed', 'cancelled', 'expired', 'unknown')
ACTIVE_STATUSES = frozenset({'created', 'dispatching', 'running', 'action_required',
                             'reported', 'send_uncertain', 'stalled', 'unobservable'})
TERMINAL_JOB_STATUSES = frozenset({'verified', 'failed', 'cancelled', 'expired'})
# Real admission evidence for the initial task send.  This is persisted apart
# from the job status so an untrusted child report can never rewrite whether
# the input was accepted.
SEND_STATES = ('pending', 'accepted', 'uncertain', 'failed')
MESSAGE_IN_FLIGHT = frozenset({'in_flight', 'claiming', 'sending'})
JOB_EVENT_LIMIT = 100
MUTABLE_FIELDS = frozenset({'status', 'status_reason', 'session_id', 'workspace',
                            'model', 'thought_level', 'effective_thought_level',
                            'workflow_mode', 'permission', 'notification', 'cursor',
                            'contract', 'profile', 'observation', 'report_payload'})
RESULT_FIELDS = ('摘要', '实际改动', '检查与证据', '未验证项', '阻碍')


class SuperagentError(ValueError):
    """A diagnosable refusal that maps directly to a tool error code."""

    def __init__(self, code, message, **details):
        self.code = str(code)
        self.details = {key: value for key, value in details.items() if value is not None}
        text = self.code + ': ' + str(message)
        super().__init__(text)


def _canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False)


def _fingerprint(*, session_id, workspace, model, thought_level, workflow_mode):
    return hashlib.sha256(_canonical({
        'session_id': str(session_id or ''),
        'workspace': str(workspace or ''),
        'model': dict(model or {}),
        'thought_level': str(thought_level or ''),
        'workflow_mode': str(workflow_mode or ''),
    }).encode('utf-8')).hexdigest()


def _sha256(text):
    return hashlib.sha256(str(text or '').encode('utf-8')).hexdigest()


def _idempotency_hash(thread_id, key):
    return hashlib.sha256((str(thread_id) + '\0' + str(key)).encode('utf-8')).hexdigest()


def _make_id(prefix):
    return prefix + uuid.uuid4().hex[:24]


def _installation_roots():
    """Directories that are plugin installation roots, never user workspaces.

    Running from this source tree, ``runtime/`` is the package root and the
    generated hosts live under ``plugins/``; both must be rejected.  An
    installed plugin has the package itself at ``.../plugins/<host>``.
    """
    package = Path(__file__).resolve()
    root = package.parent.parent
    roots = [root]
    for base in (root, root.parent):
        plugins = base / 'plugins'
        if plugins.is_dir() and plugins not in roots:
            roots.append(plugins)
            for child in sorted(plugins.iterdir()):
                if child.is_dir() and child not in roots:
                    roots.append(child)
    return roots


def bounded_report_payload(value):
    """Return (payload, truncated) bounded to MAX_REPORT_BYTES.

    The report is untrusted data.  It is kept so the owner can read it back,
    never promoted to completion evidence.  Unknown objects become strings,
    deep structures and long strings are cut, and the serialized form is
    shrunk until it fits the byte cap.
    """
    truncated = False

    def walk(item, depth):
        nonlocal truncated
        if depth > MAX_REPORT_DEPTH:
            truncated = True
            return None
        if item is None or isinstance(item, (bool, int, float)):
            return item
        if isinstance(item, str):
            if len(item) > MAX_REPORT_STRING:
                truncated = True
                return item[:MAX_REPORT_STRING]
            return item
        if isinstance(item, (list, tuple)):
            rows = []
            for index, entry in enumerate(item):
                if index >= MAX_REPORT_ITEMS:
                    truncated = True
                    break
                rows.append(walk(entry, depth + 1))
            return rows
        if isinstance(item, dict):
            rows = {}
            for index, (key, entry) in enumerate(item.items()):
                if index >= MAX_REPORT_ITEMS:
                    truncated = True
                    break
                rows[str(key)[:200]] = walk(entry, depth + 1)
            return rows
        truncated = True
        return str(item)[:200]

    payload = walk(value, 0)

    def shrink(item):
        if isinstance(item, str):
            return item[:max(0, len(item) // 2)]
        if isinstance(item, list):
            return [shrink(entry) for entry in item]
        if isinstance(item, dict):
            return {key: shrink(entry) for key, entry in item.items()}
        return item

    for _ in range(8):
        encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True,
                             default=str).encode('utf-8')
        if len(encoded) <= MAX_REPORT_BYTES:
            break
        truncated = True
        payload = shrink(payload)
    else:
        payload = {'truncated': True, 'note': 'report exceeded the byte cap'}
    return payload, truncated


def _is_inside(path, root):
    try:
        return path == root or path.is_relative_to(root)
    except AttributeError:  # Python 3.8 fallback, kept for portable hosts
        try:
            path.relative_to(root)
            return True
        except ValueError:
            return False


def normalize_source(context):
    """Whitelist the real MCP request source.  Never reads the environment."""
    context = context if isinstance(context, dict) else {}
    thread = context.get('thread_id')
    if not isinstance(thread, str) or not thread.strip():
        raise SuperagentError('source_unavailable',
                              '当前请求没有可验证的 source thread；不能猜最近会话')
    return {
        'thread_id': str(thread).strip(),
        'thread_origin': str(context.get('thread_origin') or ''),
        'request_id': str(context.get('request_id') or ''),
        'client_name': str(context.get('client_name') or ''),
        'client_version': str(context.get('client_version') or ''),
        'host_id': str(context.get('host_id') or ''),
    }


def require_caller_permission(mode):
    """Every mutation declares the actual current caller permission."""
    if mode not in PERMISSION_MODES:
        raise SuperagentError(
            'caller_permission_required',
            '必须提供 GPT 当前会话的 caller_permission_mode；无法确认时使用 always_ask')
    return mode


def _catalog_rows(catalog):
    if isinstance(catalog, dict):
        rows = catalog.get('available')
        if rows is None and isinstance(catalog.get('model'), dict):
            rows = catalog['model'].get('available')
    else:
        rows = catalog
    if not isinstance(rows, list) or not rows:
        raise SuperagentError('catalog_unavailable',
                              '没有真实的 zcode_models catalog，不能校验模型与思考强度')
    return rows


def _model_ref(row):
    ref = row.get('ref') if isinstance(row, dict) else None
    if isinstance(ref, dict) and ref.get('providerId') and ref.get('modelId'):
        return {'providerId': str(ref['providerId']), 'modelId': str(ref['modelId'])}
    if isinstance(row, dict) and row.get('providerId') and row.get('modelId'):
        return {'providerId': str(row['providerId']), 'modelId': str(row['modelId'])}
    return None


def _reasoning_levels(row):
    reasoning = row.get('reasoning') if isinstance(row, dict) else None
    reasoning = reasoning if isinstance(reasoning, dict) else {}
    values, default = [], ''
    for level in reasoning.get('levels') or ():
        value = level.get('value') if isinstance(level, dict) else level
        if isinstance(value, str) and value:
            values.append(value)
    if isinstance(reasoning.get('defaultLevel'), str):
        default = reasoning['defaultLevel']
    return values, default


def _pick(explicit, profile_row, defaults, field, default_key=None):
    """Return (value, source) for one profile field; empty strings are unset."""
    if isinstance(explicit, dict) and explicit.get(field) not in (None, ''):
        return explicit[field], 'explicit'
    if isinstance(profile_row, dict) and profile_row.get(field) not in (None, ''):
        return profile_row[field], 'profile'
    return defaults.get(default_key or field), 'default'


def _resolve_workspace_value(explicit, profile_row, defaults, configured_workspace):
    """Resolve a workspace without ever inferring it from the home directory.

    ``configured_workspace`` is the saved/explicit default supplied by the
    service layer.  When it is ``None`` (pure-function callers with a
    hand-built defaults dict) the old default field is honoured; when it is an
    empty string the caller had no genuinely configured workspace.
    """
    if isinstance(explicit, dict) and explicit.get('workspace') not in (None, ''):
        return explicit['workspace'], 'explicit'
    if isinstance(profile_row, dict) and profile_row.get('workspace') not in (None, ''):
        return profile_row['workspace'], 'profile'
    if configured_workspace is None:
        return defaults.get('default_workspace'), 'default'
    if isinstance(configured_workspace, str) and configured_workspace.strip():
        return configured_workspace, 'configured_default'
    return '', 'unset'


def _validate_workspace(value, install_roots=None):
    if not isinstance(value, str) or not value.strip():
        raise SuperagentError('workspace_required',
                              '必须提供存在的工作区：显式参数、绑定 profile 或已配置默认工作区')
    path = Path(value).expanduser()
    try:
        resolved = path.resolve()
    except OSError as error:
        raise SuperagentError('workspace_required', '工作区路径无法解析',
                              detail=type(error).__name__) from error
    if not resolved.is_dir():
        raise SuperagentError('workspace_required', '工作区不存在或不是目录')
    roots = install_roots if install_roots is not None else _installation_roots()
    for root in roots:
        try:
            root_path = Path(root).expanduser().resolve()
        except OSError:
            continue
        if _is_inside(resolved, root_path):
            raise SuperagentError(
                'workspace_required',
                '插件安装目录不能当作用户工作区；请显式指定用户项目目录')
    return str(resolved)


def resolve_profile(*, explicit=None, bound_profile='', profiles=None, defaults=None,
                    catalog=None, install_roots=None, configured_workspace=None):
    """Resolve model, reasoning level, workflow mode and workspace.

    Order per field is explicit -> bound profile -> configured default.  The
    model must exist in the supplied real catalogue and the level must be one
    of that model's levels (or ``auto``).  Failures are explicit errors; no
    value is silently replaced.
    """
    explicit = explicit if isinstance(explicit, dict) else {}
    if defaults is None:
        from .storage import config
        defaults = config()
    defaults = defaults if isinstance(defaults, dict) else {}
    profiles = profiles if profiles is not None else (defaults.get('superagent_profiles') or {})
    if not isinstance(profiles, dict):
        raise SuperagentError('profile_invalid', 'superagent_profiles 必须是对象')

    chosen = explicit.get('profile') or bound_profile or defaults.get('superagent_default_profile') or ''
    chosen = str(chosen or '')
    profile_row = {}
    if chosen:
        profile_row = profiles.get(chosen)
        if not isinstance(profile_row, dict):
            raise SuperagentError('profile_unknown', '绑定的 profile 不存在', profile=chosen)

    model, model_source = _pick(explicit, profile_row, defaults, 'model', 'default_model')
    if not isinstance(model, dict) or not model.get('providerId') or not model.get('modelId'):
        raise SuperagentError('model_required',
                              '没有可用模型：显式参数、绑定 profile 或默认值必须有 providerId/modelId')
    model = {'providerId': str(model['providerId']), 'modelId': str(model['modelId'])}

    rows = _catalog_rows(catalog)
    row = next((item for item in rows if _model_ref(item) == model), None)
    if row is None:
        raise SuperagentError(
            'model_not_in_catalog',
            '指定模型不在 ZCode 当前真实配置中；不会静默替换成别的模型',
            providerId=model['providerId'], modelId=model['modelId'])

    thought_level, thought_source = _pick(explicit, profile_row, defaults,
                                          'thought_level', 'default_thought_level')
    requested = str(thought_level or 'auto')
    levels, default_level = _reasoning_levels(row)
    if requested != 'auto' and requested not in levels:
        raise SuperagentError(
            'thought_level_unsupported',
            '该模型不支持思考强度 ' + requested + '；支持：'
            + (', '.join(levels) if levels else '（catalog 未提供）'),
            thought_level=requested, supported=levels)
    effective = requested if requested != 'auto' else (default_level or (levels[0] if levels else 'auto'))

    workflow_mode, workflow_source = _pick(explicit, profile_row, defaults,
                                           'workflow_mode', 'default_workflow_mode')
    workflow_mode = str(workflow_mode or 'onDemand')
    if workflow_mode not in WORKFLOW_MODES:
        raise SuperagentError('workflow_mode_invalid', '工作流模式无效', workflow_mode=workflow_mode)

    transport, transport_source = _pick(explicit, profile_row, defaults,
                                        'transport', 'default_transport')
    transport = str(transport or 'desktop_native')
    if transport not in TRANSPORTS:
        raise SuperagentError('independent_engine_disabled', '只支持唯一 Desktop 的 desktop_native 后端',
                              transport=transport)

    workspace, workspace_source = _resolve_workspace_value(
        explicit, profile_row, defaults, configured_workspace)
    workspace = _validate_workspace(workspace, install_roots=install_roots)

    return {
        'profile': chosen,
        'model': model,
        'thought_level': requested,
        'effective_thought_level': effective or 'auto',
        'workflow_mode': workflow_mode,
        'transport': transport,
        'workspace': workspace,
        'catalog_validated': True,
        'sources': {
            'model': model_source,
            'thought_level': thought_source,
            'workflow_mode': workflow_source,
            'transport': transport_source,
            'workspace': workspace_source,
        },
    }


def resolve_workspace(*, explicit=None, bound_profile='', profiles=None, defaults=None,
                      install_roots=None, configured_workspace=None):
    """Resolve only the workspace, before a real model catalogue is fetched."""
    explicit = explicit if isinstance(explicit, dict) else {}
    if defaults is None:
        from .storage import config
        defaults = config()
    defaults = defaults if isinstance(defaults, dict) else {}
    profiles = profiles if profiles is not None else (defaults.get('superagent_profiles') or {})
    if not isinstance(profiles, dict):
        raise SuperagentError('profile_invalid', 'superagent_profiles 必须是对象')
    chosen = explicit.get('profile') or bound_profile or defaults.get('superagent_default_profile') or ''
    chosen = str(chosen or '')
    profile_row = {}
    if chosen:
        profile_row = profiles.get(chosen)
        if not isinstance(profile_row, dict):
            raise SuperagentError('profile_unknown', '绑定的 profile 不存在', profile=chosen)
    workspace, source = _resolve_workspace_value(
        explicit, profile_row, defaults, configured_workspace)
    return {
        'profile': chosen,
        'workspace': _validate_workspace(workspace, install_roots=install_roots),
        'source': source,
    }


def build_task_prompt(task_text, job, *, revision=False, later=False,
                      completion='', report_tool='zcode_agent_report'):
    """Attach the task-context contract without changing the task text.

    The returned prompt always starts with the exact original task text.  A
    task that starts with ``/workflow`` keeps its first line untouched, so the
    native slash-command semantics survive; the contract is appended after it.
    ``later`` messages get only a short reference.  A revision gets the full
    contract again with an explicit revision marker.
    """
    if not isinstance(task_text, str) or not task_text.strip():
        raise SuperagentError('task_required', '任务原文不能为空')
    job = job if isinstance(job, dict) else {}
    job = copy.deepcopy(job)
    job_id = str(job.get('job_id') or '')
    agent_id = str(job.get('agent_id') or '')
    model = job.get('model') or {}
    permission = job.get('permission') or {}
    if later and not revision:
        reference = (
            '\n\n[' + CONTRACT_VERSION + '] agent=' + agent_id + ' job=' + job_id
            + '。沿用首次发送的完整契约；配置与完成条件未变。'
            + '当前状态：' + str(job.get('status') or 'unknown') + '。')
        return task_text + reference

    criteria = str(completion or '按任务原文完成，并以可复核的检查证据证明；不得只报告“通过”。')
    revision_line = '修订：本次为任务或配置修订，重新附完整契约。\n' if revision else ''
    if report_tool:
        report_line = (
            '- 最终结果用 ' + str(report_tool) + '(agent_id=' + agent_id
            + ', result={...}) 报告；agent_id 已绑定父会话，session_id 可省略；'
            '普通进度不是完成。\n')
    else:
        # Native creation has no session reportMCP.  Never instruct the child to
        # call a tool that is not loaded; the structured return is the result.
        report_line = (
            '- 当前会话没有 zcode_agent_report MCP：最终结果直接在回复中按下方字段'
            '结构化返回，不要调用不存在的工具，也不要为 report 递归调用旧桥接插件；'
            '若该工具明确可用，才可额外 report。普通进度不是完成。\n')
    contract = (
        '\n\n[' + CONTRACT_VERSION + ']\n'
        + revision_line
        + 'agent_id: ' + agent_id + '\n'
        + 'job_id: ' + job_id + '\n'
        + '任务范围与完成条件：\n'
        + '- 范围：上方任务原文即唯一范围；不要扩展到未要求的文件、仓库或发布动作。\n'
        + '- 完成条件：' + criteria + '\n'
        + '当前配置：\n'
        + '- workspace: ' + str(job.get('workspace') or '') + '\n'
        + '- model: ' + str(model.get('providerId') or '') + '/' + str(model.get('modelId') or '') + '\n'
        + '- thought_level: ' + str(job.get('thought_level') or 'auto') + '\n'
        + '- effective_thought_level: ' + str(job.get('effective_thought_level') or 'auto') + '\n'
        + '- workflow_mode: ' + str(job.get('workflow_mode') or '') + '\n'
        + '- caller_permission_mode: ' + str(permission.get('declared') or '')
        + '（来源：' + str(permission.get('source') or 'explicit_caller') + '）\n'
        + '如何报告与提问：\n'
        + '- 需要父代理或用户决定时，优先使用原生 AskUserQuestion/权限请求；父侧会用 '
          'zcode_agent_answer 回答真实 request_id，不要伪造选项。\n'
        + '- 若你是 DWF 子代理且当前平台没有原生 AskUserQuestion，先以结构化 '
          'needs_input 返回给 ZCode 主会话（写清问题、选项与阻塞点），由主会话用原生 '
          'AskUserQuestion 向外部父代理转交；收到答案后带着继续，不要自行代答。\n'
        + report_line
        + '结构化最终结果字段（必须逐项填写）：\n'
        + '\n'.join('- ' + field for field in RESULT_FIELDS) + '\n'
        + '边界：子端自述只是 reported；完成由桥接按真实终态证据判定。'
          '不要索取或输出凭据、宿主 pipe、其他会话内容。')
    return task_text + contract


class SuperagentStore:
    """Atomic, thread-scoped job store; one instance per daemon or test."""

    def __init__(self, path=None, clock=time.time):
        self.path = Path(path) if path else (state_dir() / 'superagent.json')
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.clock = clock
        self.lock = threading.RLock()
        self.data = self._load()
        # A claimed queue item whose outcome was never recorded means the
        # process died after persisting the claim (or during the send).  It is
        # unknown whether the message reached the engine, so it must never be
        # treated as an ordinary queued item and resent automatically.
        with self.lock:
            if self._recover_in_flight_locked():
                self._save_locked()

    # ------------------------------------------------------------- persistence
    def _empty(self):
        return {'schema': SCHEMA_VERSION, 'next_sequence': 1, 'jobs': {}}

    def _load(self):
        raw = read_json(self.path, None)
        if raw is None:
            if self.path.exists():
                self._quarantine()
            return self._empty()
        if (not isinstance(raw, dict) or raw.get('schema') != SCHEMA_VERSION
                or not isinstance(raw.get('jobs'), dict)):
            self._quarantine()
            return self._empty()
        raw.setdefault('next_sequence', 1)
        return raw

    def _quarantine(self):
        try:
            target = self.path.with_name(self.path.name + '.incompatible-' + uuid.uuid4().hex[:8])
            os.replace(self.path, target)
        except OSError:
            pass

    def _recover_in_flight_locked(self):
        """Close claims left behind by a process exit before the send outcome.

        The claim was persisted before the side-effecting send, so after a
        restart the only honest state is ``uncertain``: the message may or may
        not have been admitted.  Only ``queued`` items are ever sent again.
        """
        now = float(self.clock())
        changed = False
        for job in (self.data.get('jobs') or {}).values():
            recovered = 0
            for item in job.get('queue') or ():
                if item.get('state') not in MESSAGE_IN_FLIGHT:
                    continue
                item['state'] = 'uncertain'
                item['last_error_type'] = 'restart_in_flight'
                item['interrupted_at'] = now
                item['updated_at'] = now
                recovered += 1
            if not recovered:
                continue
            self._append_job_event_locked(
                job, 'job.message_uncertain', 'restart_in_flight',
                now, job.get('status'))
            job['updated_at'] = now
            changed = True
        return changed

    def _save_locked(self, now=None):
        now = float(now if now is not None else self.clock())
        jobs = self.data['jobs']
        if len(jobs) > MAX_JOBS:
            order = sorted(jobs.values(), key=lambda row: (
                str(row.get('status')) in ACTIVE_STATUSES,
                float(row.get('updated_at') or 0)))
            for row in order:
                if len(jobs) <= MAX_JOBS:
                    break
                if str(row.get('status')) in ACTIVE_STATUSES:
                    continue
                jobs.pop(row.get('job_id'), None)
        write_json(self.path, self.data)

    # ----------------------------------------------------------------- lookup
    @staticmethod
    def _thread_of(job):
        return str(((job or {}).get('source') or {}).get('thread_id') or '')

    def _get_locked(self, job_id, thread_id):
        job = self.data['jobs'].get(str(job_id))
        if job is None or self._thread_of(job) != str(thread_id):
            return None
        return job

    def _find_idempotency_locked(self, thread_id, key_hash):
        for job in self.data['jobs'].values():
            if self._thread_of(job) == str(thread_id) and job.get('idempotency_key_hash') == key_hash:
                return job
        return None

    def get(self, job_id, thread_id):
        """Read one job only from its own source thread."""
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            return copy.deepcopy(job) if job is not None else None

    def list(self, thread_id, limit=50):
        """Newest jobs for one source thread, never another thread's jobs."""
        limit = min(200, max(1, int(limit or 50)))
        with self.lock:
            rows = [copy.deepcopy(job) for job in self.data['jobs'].values()
                    if self._thread_of(job) == str(thread_id)]
        rows.sort(key=lambda job: (float(job.get('created_at') or 0),
                                   str(job.get('job_id') or '')), reverse=True)
        return rows[:limit]

    def find_by_idempotency(self, thread_id, key):
        """Return an already persisted job for a delegate key, if any."""
        if not isinstance(key, str) or not key.strip():
            return None
        key_hash = _idempotency_hash(thread_id, key.strip())
        with self.lock:
            job = self._find_idempotency_locked(thread_id, key_hash)
            return copy.deepcopy(job) if job is not None else None

    def find_agent(self, agent_id, thread_id):
        agent_id = str(agent_id or '')
        if not agent_id:
            return None
        with self.lock:
            for job in self.data['jobs'].values():
                if job.get('agent_id') == agent_id and self._thread_of(job) == str(thread_id):
                    return copy.deepcopy(job)
        return None

    def find_agent_any(self, agent_id):
        """Internal lookup used only to distinguish not-found from session mismatch."""
        agent_id = str(agent_id or '')
        if not agent_id:
            return None
        with self.lock:
            for job in self.data['jobs'].values():
                if job.get('agent_id') == agent_id:
                    return copy.deepcopy(job)
        return None

    def find_for_report(self, agent_id, session_id):
        """Narrow cross-thread lookup for the untrusted child report channel."""
        agent_id, session_id = str(agent_id or ''), str(session_id or '')
        if not agent_id or not session_id:
            return None
        with self.lock:
            for job in self.data['jobs'].values():
                if (job.get('agent_id') == agent_id
                        and job.get('session_id') == session_id):
                    return copy.deepcopy(job)
        return None

    def all_active(self):
        """Internal daemon view for queue draining; never exposed to a tool."""
        with self.lock:
            return [copy.deepcopy(job) for job in self.data['jobs'].values()
                    if str(job.get('status')) in ACTIVE_STATUSES]

    # ----------------------------------------------------------------- create
    def create_job(self, source, config, *, caller_permission_mode,
                   idempotency_key=None, session_id='', task_text='',
                   install_roots=None):
        """Create or return one delegation.  Never dispatches by itself.

        Returns ``{'job': ..., 'created': bool, 'idempotency_key': ...,
        'conflict': bool}``.  A conflicting replay is still the same job: it is
        reported, not re-created and never re-dispatched.
        """
        source = normalize_source(source)
        mode = require_caller_permission(caller_permission_mode)
        if not isinstance(config, dict):
            raise SuperagentError('profile_invalid', '解析后的配置必须是对象')
        if config.get('catalog_validated') is not True:
            raise SuperagentError('catalog_unavailable',
                                  '配置必须先用真实 zcode_models catalog 解析；不能直接创建未校验的委托')
        workspace = _validate_workspace(config.get('workspace'), install_roots=install_roots)
        model = config.get('model')
        if not isinstance(model, dict) or not model.get('providerId') or not model.get('modelId'):
            raise SuperagentError('model_required', '解析后的配置缺少模型')
        thought_level = str(config.get('thought_level') or 'auto')
        workflow_mode = str(config.get('workflow_mode') or 'onDemand')
        if workflow_mode not in WORKFLOW_MODES:
            raise SuperagentError('workflow_mode_invalid', '工作流模式无效')

        key = idempotency_key
        if key is None or (isinstance(key, str) and not key.strip()):
            key = _make_id('idem_')
        if not isinstance(key, str) or not key.strip() or len(key) > MAX_IDEMPOTENCY_CHARS:
            raise SuperagentError('idempotency_key_invalid',
                                  'idempotency_key 必须是 1-' + str(MAX_IDEMPOTENCY_CHARS) + ' 字符的字符串')
        key = key.strip()
        key_hash = _idempotency_hash(source['thread_id'], key)
        fingerprint = _fingerprint(session_id=session_id, workspace=workspace, model=model,
                                   thought_level=thought_level, workflow_mode=workflow_mode)
        task_sha = _sha256(task_text)
        now = float(self.clock())

        with self.lock:
            existing = self._find_idempotency_locked(source['thread_id'], key_hash)
            if existing is not None:
                conflict = (existing.get('request_fingerprint') != fingerprint
                            or (task_sha and existing.get('task_sha256')
                                and existing.get('task_sha256') != task_sha))
                return {'job': copy.deepcopy(existing), 'created': False,
                        'idempotency_key': existing.get('idempotency_key') or key,
                        'conflict': bool(conflict)}

            sequence = int(self.data.get('next_sequence') or 1)
            self.data['next_sequence'] = sequence + 1
            job = {
                'schema': SCHEMA_VERSION,
                'sequence': sequence,
                'agent_id': _make_id('agent_'),
                'job_id': _make_id('job_'),
                'created_at': now,
                'updated_at': now,
                'status': 'created',
                'status_reason': '',
                'send': {'state': 'pending', 'accepted': False,
                         'retry_required': False, 'reason': 'not_sent',
                         'error_type': '', 'at': None},
                'source': source,
                'session_id': str(session_id or ''),
                'workspace': workspace,
                'model': {'providerId': str(model['providerId']),
                          'modelId': str(model['modelId'])},
                'thought_level': thought_level,
                'effective_thought_level': str(config.get('effective_thought_level')
                                               or thought_level),
                'workflow_mode': workflow_mode,
                'transport': str(config.get('transport') or 'engine'),
                'profile': str(config.get('profile') or ''),
                'permission': {
                    'declared': mode,
                    'source': 'explicit_caller',
                    'thread_origin': source.get('thread_origin') or '',
                    'request_id': source.get('request_id') or '',
                },
                'idempotency_key': key,
                'idempotency_key_hash': key_hash,
                'request_fingerprint': fingerprint,
                'task_sha256': task_sha,
                'task_chars': int(len(task_text or '')),
                'notification': {
                    'subscription_id': '',
                    'armed': False,
                    'completion_notify': False,
                    'auto_continue': False,
                    'user_authorized': False,
                    'reason': 'not_requested',
                },
                'cursor': {'after_message_id': '', 'event_cursor': 0},
                'queue': [],
                'delivered_messages': [],
                'last_progress': {'at': None, 'kind': '', 'message_id': '', 'status': '',
                                  'activity': {}, 'run_watermarks': {}},
                'read_failures': {'consecutive': 0, 'last_error_type': '', 'last_at': None},
                'observation': {'checked_at': None, 'engine_status': '',
                                'engine_idle': False, 'active_background': None,
                                'last_message_id': ''},
                'report_payload': None,
                'report': None,
                'events': [],
                'contract': {'version': CONTRACT_VERSION, 'revision': 0, 'sent_at': None},
            }
            self.data['jobs'][job['job_id']] = job
            self._save_locked(now)
            return {'job': copy.deepcopy(job), 'created': True,
                    'idempotency_key': key, 'conflict': False}

    # ----------------------------------------------------------------- mutate
    def update_job(self, job_id, thread_id, **changes):
        unknown = set(changes) - MUTABLE_FIELDS
        if unknown:
            raise SuperagentError('field_not_mutable', '不能修改这些字段',
                                  fields=sorted(unknown))
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            for key, value in changes.items():
                job[key] = copy.deepcopy(value)
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    def set_status(self, job_id, thread_id, status, reason=''):
        if status not in STATUSES:
            raise SuperagentError('status_invalid', '未知 job 状态', status=status)
        return self.update_job(job_id, thread_id, status=status,
                               status_reason=str(reason or ''))

    def _append_job_event_locked(self, job, kind, reason, at, status):
        event_id = 'jevt_' + hashlib.sha256(_canonical(
            [job.get('job_id'), kind, reason]).encode('utf-8')).hexdigest()[:24]
        events = job.setdefault('events', [])
        if any(row.get('event_id') == event_id for row in events):
            return None
        event = {'event_id': event_id, 'kind': kind, 'reason': reason,
                 'at': at, 'status': status}
        events.append(event)
        del events[:-JOB_EVENT_LIMIT]
        return event

    def _transition_locked(self, job, status, reason, event_kind=None):
        if status not in STATUSES:
            raise SuperagentError('status_invalid', '未知 job 状态', status=status)
        reason = str(reason or '')
        now = float(self.clock())
        changed = (job.get('status') != status
                   or str(job.get('status_reason') or '') != reason)
        event = None
        if event_kind:
            event = self._append_job_event_locked(job, event_kind, reason or status,
                                                  now, status)
        if changed:
            job['status'] = status
            job['status_reason'] = reason
        if changed or event is not None:
            job['updated_at'] = now
        return event, changed

    def transition(self, job_id, thread_id, status, reason='', event_kind=None):
        """Move a job state once; one event per job/kind/reason is persisted."""
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            if (job.get('status') in TERMINAL_JOB_STATUSES
                    and status not in TERMINAL_JOB_STATUSES):
                return copy.deepcopy(job)
            event, changed = self._transition_locked(job, status, reason, event_kind)
            if changed or event is not None:
                self._save_locked()
            result = copy.deepcopy(job)
            result['last_event'] = copy.deepcopy(event)
            return result

    def apply_verification(self, job_id, thread_id, status, reason=''):
        """Apply bridge evidence only.  Never upgrades 'reported' by itself."""
        if status not in TERMINAL_JOB_STATUSES:
            raise SuperagentError('verification_invalid', '验证状态无效', status=status)
        event_kind = {'verified': 'job.verified', 'failed': 'job.failed',
                      'cancelled': 'job.cancelled', 'expired': 'job.expired'}[status]
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            if job.get('status') in TERMINAL_JOB_STATUSES:
                if job.get('status') != status:
                    return copy.deepcopy(job)
            event, changed = self._transition_locked(job, status, reason, event_kind)
            if changed or event is not None:
                self._save_locked()
            result = copy.deepcopy(job)
            result['last_event'] = copy.deepcopy(event)
            return result

    def set_session(self, job_id, thread_id, session_id):
        return self.update_job(job_id, thread_id, session_id=str(session_id or ''))

    def set_notification(self, job_id, thread_id, **fields):
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            notification = dict(job.get('notification') or {})
            allowed = {'subscription_id', 'armed', 'completion_notify', 'auto_continue',
                       'user_authorized', 'reason'}
            notification.update({key: value for key, value in fields.items() if key in allowed})
            job['notification'] = notification
            job['updated_at'] = float(self.clock())
            self._save_locked()
            return copy.deepcopy(job)

    def set_cursor(self, job_id, thread_id, *, after_message_id=None, event_cursor=None):
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            cursor = dict(job.get('cursor') or {})
            if after_message_id is not None:
                cursor['after_message_id'] = str(after_message_id)
            if event_cursor is not None:
                cursor['event_cursor'] = max(0, int(event_cursor))
            job['cursor'] = cursor
            job['updated_at'] = float(self.clock())
            self._save_locked()
            return copy.deepcopy(job)

    @staticmethod
    def _normalize_watermarks(value):
        """Bound the per-run ``{run_id: {epoch, cursor}}`` watermark map."""
        rows = []
        for key, entry in value.items():
            if isinstance(entry, dict):
                run_id = str(key)[:200]
                epoch = str(entry.get('epoch') or '')[:200]
                try:
                    cursor = max(0, int(entry.get('cursor') or 0))
                except (TypeError, ValueError):
                    continue
            else:
                # Migrate the earlier flat ``epoch:run_id -> cursor`` shape.
                full = str(key)
                epoch, run_id = (full.rsplit(':', 1) if ':' in full else ('', full))
                try:
                    cursor = max(0, int(entry or 0))
                except (TypeError, ValueError):
                    continue
            if not run_id:
                continue
            rows.append((run_id[:200], {'epoch': epoch, 'cursor': cursor}))
        return dict(sorted(rows)[:128])

    def record_progress(self, job_id, thread_id, *, kind='', message_id='', status='',
                        activity=None, run_watermarks=None, at=None,
                        reset_failures=True):
        """Record the last observable progress and reset read-failure counters.

        ``activity`` is a compact, body-free dict (known child ids, child stream
        metadata and a message activity digest).  ``run_watermarks`` is the
        per-epoch/per-run cursor high-water map; the caller only advances it
        for strictly forward cursors.  Passing either as ``None`` preserves
        the previous value because callers such as ``inspect`` observe without
        re-reading workflows.  ``at`` keeps the stall window deterministic for
        a caller with an explicit sync clock.  ``reset_failures=False`` keeps a
        concurrent read-failure streak visible while still recording a real
        parent/message change.
        """
        now = float(at if at is not None else self.clock())
        progress = {'at': now, 'kind': str(kind or '')[:40],
                    'message_id': str(message_id or '')[:160], 'status': str(status or '')[:40]}
        if isinstance(activity, dict):
            progress['activity'] = {str(key)[:24]: str(value)[:160]
                                    for key, value in activity.items()
                                    if value is not None and str(value) != ''}
        if isinstance(run_watermarks, dict):
            progress['run_watermarks'] = self._normalize_watermarks(run_watermarks)
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            previous = job.get('last_progress') or {}
            if not isinstance(activity, dict) and isinstance(previous.get('activity'), dict):
                progress['activity'] = copy.deepcopy(previous['activity'])
            if not isinstance(run_watermarks, dict) \
                    and isinstance(previous.get('run_watermarks'), dict):
                progress['run_watermarks'] = copy.deepcopy(previous['run_watermarks'])
            job['last_progress'] = progress
            if reset_failures:
                job['read_failures'] = {'consecutive': 0, 'last_error_type': '',
                                        'last_at': None}
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    def record_read_failure(self, job_id, thread_id, error_type):
        """Count consecutive observation failures without storing messages."""
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return 0
            failures = dict(job.get('read_failures') or {})
            failures['consecutive'] = int(failures.get('consecutive') or 0) + 1
            failures['last_error_type'] = str(error_type or '')[:80]
            failures['last_at'] = now
            job['read_failures'] = failures
            job['updated_at'] = now
            self._save_locked(now)
            return failures['consecutive']

    def update_run_watermarks(self, job_id, thread_id, watermarks):
        """Persist a new epoch/membership baseline without refreshing progress.

        A new epoch's first cursor is a new fact, not progress: ``last_progress.at``,
        the activity dict and the read-failure streak stay unchanged.  A later
        strictly greater cursor in that epoch goes through ``record_progress``.
        """
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            progress = dict(job.get('last_progress') or {})
            progress['run_watermarks'] = self._normalize_watermarks(watermarks)
            job['last_progress'] = progress
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    def reset_read_failures(self, job_id, thread_id):
        """A clean read breaks the consecutive-failure streak without progress."""
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            failures = job.get('read_failures') or {}
            if int(failures.get('consecutive') or 0) == 0:
                return copy.deepcopy(job)
            job['read_failures'] = {'consecutive': 0, 'last_error_type': '', 'last_at': None}
            job['updated_at'] = float(self.clock())
            self._save_locked()
            return copy.deepcopy(job)

    def set_contract_sent(self, job_id, thread_id, *, revision=False):
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            contract = dict(job.get('contract') or {})
            contract['version'] = CONTRACT_VERSION
            contract['sent_at'] = float(self.clock())
            contract['revision'] = int(contract.get('revision') or 0) + (1 if revision else 0)
            job['contract'] = contract
            job['updated_at'] = float(self.clock())
            self._save_locked()
            return copy.deepcopy(job)

    def set_send_state(self, job_id, thread_id, state, reason='', error_type=''):
        """Persist real admission evidence for the initial task send.

        Only the bridge writes this from an actual send outcome.  ``accepted``
        is never downgraded by later weaker evidence (for example a follow-up
        message failure), and a report hint never reaches this method.
        """
        if state not in SEND_STATES:
            raise SuperagentError('send_state_invalid', '未知发送状态', state=state)
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            current = job.get('send') if isinstance(job.get('send'), dict) else {}
            if str(current.get('state') or '') == 'accepted' and state != 'accepted':
                state = 'accepted'
                reason = current.get('reason') or reason
                error_type = current.get('error_type') or error_type
            job['send'] = {'state': state, 'accepted': state == 'accepted',
                           'retry_required': state == 'uncertain',
                           'reason': str(reason or '')[:120],
                           'error_type': str(error_type or '')[:80],
                           'at': now}
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    # ------------------------------------------------------------------ queue
    def enqueue_message(self, job_id, thread_id, content, idempotency_key=None,
                        caller_permission_mode=None):
        """Append one bounded follow-up.  Same key never queues twice."""
        if not isinstance(content, str) or not content.strip():
            raise SuperagentError('message_required', '跟进消息不能为空')
        if len(content) > MAX_MESSAGE_CHARS:
            raise SuperagentError('message_too_large',
                                  '单条消息不能超过 ' + str(MAX_MESSAGE_CHARS) + ' 字符')
        if caller_permission_mode is not None:
            require_caller_permission(caller_permission_mode)
        key = idempotency_key
        if isinstance(key, str) and not key.strip():
            key = None
        if key is not None:
            if not isinstance(key, str) or not key.strip() or len(key) > MAX_IDEMPOTENCY_CHARS:
                raise SuperagentError('idempotency_key_invalid', 'idempotency_key 格式无效')
            key = key.strip()
        key_hash = _idempotency_hash(thread_id, key) if key else ''
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            queue = list(job.get('queue') or [])
            if key_hash:
                for index, item in enumerate(queue):
                    if item.get('idempotency_key_hash') == key_hash:
                        return {'state': 'duplicate', 'message_id': item.get('message_id'),
                                'position': index + 1}
                for item in job.get('delivered_messages') or ():
                    if isinstance(item, dict) and item.get('idempotency_key_hash') == key_hash:
                        return {'state': 'duplicate', 'message_id': item.get('message_id'),
                                'position': 0, 'delivered': True}
            if len(queue) >= MAX_QUEUE_ITEMS:
                raise SuperagentError('queue_full',
                                      '跟进队列已满；先等待已排队消息投递或取消任务',
                                      limit=MAX_QUEUE_ITEMS)
            message_id = _make_id('msg_')
            queue.append({'message_id': message_id, 'content': content,
                          'idempotency_key_hash': key_hash, 'queued_at': now,
                          'caller_permission_mode': str(caller_permission_mode or ''),
                          'state': 'queued'})
            job['queue'] = queue
            job['updated_at'] = now
            self._save_locked(now)
            return {'state': 'queued', 'message_id': message_id, 'position': len(queue)}

    def take_next_message(self, job_id, thread_id):
        """Pop the oldest queued message for a safe-idle send."""
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            queue = list(job.get('queue') or [])
            if not queue:
                return None
            item = queue.pop(0)
            job['queue'] = queue
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(item)

    def queue_size(self, job_id, thread_id):
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            return len(job.get('queue') or []) if job is not None else 0

    def mark_message_delivered(self, job_id, thread_id, message_id, idempotency_key_hash=''):
        """Remember a successful delivery so the same key is never re-queued."""
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            delivered = list(job.get('delivered_messages') or [])
            if idempotency_key_hash:
                delivered.append({'message_id': str(message_id or ''),
                                  'idempotency_key_hash': str(idempotency_key_hash),
                                  'at': now})
                delivered = delivered[-50:]
            job['delivered_messages'] = delivered
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    # ------------------------------------------------------------------ views
    def peek_next_message(self, job_id, thread_id):
        """Return the oldest still-queued message without claiming it."""
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            for item in job.get('queue') or ():
                if item.get('state') == 'queued':
                    return copy.deepcopy(item)
            return None

    @staticmethod
    def _claim_locked(item, now):
        item['state'] = 'in_flight'
        item['claim_id'] = _make_id('claim_')
        item['attempts'] = int(item.get('attempts') or 0) + 1
        item['claimed_at'] = now
        item['updated_at'] = now

    def claim_next_message(self, job_id, thread_id):
        """Atomically claim the oldest queued message and persist the claim.

        The claim is durable before the caller performs any side-effecting
        send.  A second caller therefore finds nothing to claim, and a restart
        after a crash recovers the item as ``uncertain`` instead of resending.
        """
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            for item in job.get('queue') or ():
                if item.get('state') != 'queued':
                    continue
                self._claim_locked(item, now)
                job['updated_at'] = now
                self._save_locked(now)
                return copy.deepcopy(item)
            return None

    def claim_message(self, job_id, thread_id, message_id):
        """Compare-and-set claim of one queued message; None if already taken."""
        now = float(self.clock())
        message_id = str(message_id or '')
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            for item in job.get('queue') or ():
                if (item.get('message_id') != message_id
                        or item.get('state') != 'queued'):
                    continue
                self._claim_locked(item, now)
                job['updated_at'] = now
                self._save_locked(now)
                return copy.deepcopy(item)
            return None

    def complete_message(self, job_id, thread_id, message_id):
        """Remove a delivered message and remember its idempotency key."""
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            queue = [item for item in (job.get('queue') or ())
                     if item.get('message_id') != str(message_id)]
            removed = next((item for item in (job.get('queue') or ())
                            if item.get('message_id') == str(message_id)), None)
            job['queue'] = queue
            if removed and removed.get('idempotency_key_hash'):
                delivered = list(job.get('delivered_messages') or [])
                delivered.append({'message_id': removed.get('message_id'),
                                  'idempotency_key_hash': removed.get('idempotency_key_hash'),
                                  'at': now})
                job['delivered_messages'] = delivered[-50:]
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    def mark_message_state(self, job_id, thread_id, message_id, state, error_type=''):
        """Keep an uncertain/failed queued message without auto-resending it."""
        if state not in ('queued', 'uncertain', 'not_accepted', 'not_delivered',
                         'delivered'):
            raise SuperagentError('message_state_invalid', '未知消息状态', state=state)
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            for item in job.get('queue') or ():
                if item.get('message_id') == str(message_id):
                    item['state'] = state
                    item['last_error_type'] = str(error_type or '')[:80]
                    item['updated_at'] = now
                    break
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    def clear_queue(self, job_id, thread_id):
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            job['queue'] = []
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    def mark_queue_not_delivered(self, job_id, thread_id, reason='agent_terminal'):
        """Close undelivered follow-ups with a stable diagnostic event."""
        now = float(self.clock())
        with self.lock:
            job = self._get_locked(job_id, thread_id)
            if job is None:
                return None
            undelivered = [item for item in (job.get('queue') or ())
                           if item.get('state') != 'delivered']
            if not undelivered:
                return copy.deepcopy(job)
            for item in undelivered:
                item['state'] = 'not_delivered'
                item['last_error_type'] = str(reason or 'agent_terminal')[:80]
                item['updated_at'] = now
            self._append_job_event_locked(
                job, 'job.message_not_delivered', str(reason or 'agent_terminal'),
                now, job.get('status'))
            job['updated_at'] = now
            self._save_locked(now)
            return copy.deepcopy(job)

    def record_report(self, job_id, report, payload=None):
        """Store an unverified digest plus an optional bounded private payload.

        The payload stays untrusted data: it is never completion evidence and
        is only returned through an owner-scoped ``include_report`` read.  Job
        events carry no report body.
        """
        with self.lock:
            job = self.data['jobs'].get(str(job_id))
            if job is None:
                return None
            job['report'] = copy.deepcopy(report)
            if payload is not None:
                job['report_payload'] = copy.deepcopy(payload)
            # The report is only a hint.  It may move a healthy job to
            # 'reported', but it must never erase a diagnostic send state.
            if job.get('status') in ('running', 'created', 'dispatching', 'reported'):
                self._transition_locked(job, 'reported', 'unverified_hint',
                                        'job.reported')
            else:
                # Do not erase an actionable/diagnostic state with a hint.
                job['updated_at'] = float(self.clock())
            self._save_locked()
            return copy.deepcopy(job)

    @staticmethod
    def job_summary(job, include_report=False):
        """Compact view suitable for a tool response.

        The report body is excluded unless the owner explicitly asks for it;
        the default response carries only the digest and field names.
        """
        job = job if isinstance(job, dict) else {}
        queue = job.get('queue') or []
        return {
            'agent_id': job.get('agent_id'),
            'job_id': job.get('job_id'),
            'status': job.get('status'),
            'status_reason': job.get('status_reason'),
            'send': copy.deepcopy(job.get('send')),
            'verification_scope': 'turn_lifecycle',
            'task_success': None,
            'task_review': 'needs_parent_review',
            'session_id': job.get('session_id'),
            'workspace': job.get('workspace'),
            'model': copy.deepcopy(job.get('model')),
            'thought_level': job.get('thought_level'),
            'effective_thought_level': job.get('effective_thought_level'),
            'workflow_mode': job.get('workflow_mode'),
            'transport': job.get('transport') or 'engine',
            'profile': job.get('profile'),
            'permission': copy.deepcopy(job.get('permission')),
            'idempotency_key': job.get('idempotency_key'),
            'notification': copy.deepcopy(job.get('notification')),
            'cursor': copy.deepcopy(job.get('cursor')),
            'queue': {'count': len(queue), 'limit': MAX_QUEUE_ITEMS,
                      'positions': [{'message_id': item.get('message_id'),
                                     'queued_at': item.get('queued_at'),
                                     'state': item.get('state') or 'queued',
                                     'last_error_type': item.get('last_error_type') or ''}
                                    for item in queue]},
            'delivered_messages': len(job.get('delivered_messages') or []),
            'last_progress': copy.deepcopy(job.get('last_progress')),
            'read_failures': copy.deepcopy(job.get('read_failures')),
            'observation': copy.deepcopy(job.get('observation')),
            'report': copy.deepcopy(job.get('report')),
            'report_payload': (copy.deepcopy(job.get('report_payload'))
                               if include_report else None),
            'events': copy.deepcopy(job.get('events') or [])[-20:],
            'contract': copy.deepcopy(job.get('contract')),
            'created_at': job.get('created_at'),
            'updated_at': job.get('updated_at'),
        }
